const quoteFor = (items: Item[]): Result => {
  const policyBase = policyBaseOf(items);
  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
  return {
    premium: premiumRoundedInMHPCOsFavour(
      riskAdjustedBase + policyModifiersOn(policyBase) + PROCESSING_FEE,
    ),
  };
};
